// unavailable answers 503 wherever the store could not be opened, so a
// misconfigured DATA_DIR shows up in the probes instead of in a panic.
func unavailable() http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.URL.Path == "/healthz" {
			writeError(w, http.StatusServiceUnavailable, "store unavailable")
			return
		}
		http.NotFound(w, r)
	})
}

func (s *Server) routes() {
	s.mux.HandleFunc("GET /healthz", s.healthz)
	// signup creates an account as the store contract says; the auth card
	// takes it over with bcrypt hashing and the password's own rules.
	s.mux.HandleFunc("POST /api/signup", s.signup)
	// The auth card takes these over with its own handlers; they answer
	// 401 until it does, because the session middleware has no login to
	// read a cookie of yet.
	s.mux.HandleFunc("GET /api/me", s.requireUser(func(w http.ResponseWriter, _ *http.Request, u *store.User) {
		writeJSON(w, http.StatusOK, map[string]any{"id": u.ID, "email": u.Email})
	}))
	s.mux.Handle("/api/", http.NotFoundHandler())
	s.mux.Handle("/app/", http.StripPrefix("/app", app()))
	s.mux.Handle("GET /{$}", http.RedirectHandler("/app/", http.StatusFound))
}

func (s *Server) healthz(w http.ResponseWriter, _ *http.Request) {
	writeJSON(w, http.StatusOK, map[string]string{"status": "ok"})
}

// signup passes a valid-looking body to store.CreateUser, so the contract
// between the API and the store runs end to end.
func (s *Server) signup(w http.ResponseWriter, r *http.Request) {
	var body struct {
		Email    string `json:"email"`
		Password string `json:"password"`
	}
	if err := json.NewDecoder(io.LimitReader(r.Body, maxBodyBytes)).Decode(&body); err != nil {
		writeError(w, http.StatusBadRequest, "invalid JSON body")
		return
	}
	body.Email = strings.TrimSpace(body.Email)
	if body.Email == "" || !strings.Contains(body.Email, "@") {
		writeError(w, http.StatusBadRequest, "a valid email is required")
		return
	}
	if body.Password == "" {
		writeError(w, http.StatusBadRequest, "a password is required")
		return
	}
	u, err := s.store.CreateUser(r.Context(), body.Email, body.Password)
	if err != nil {
		switch {
		case errors.Is(err, store.ErrDuplicate):
			writeError(w, http.StatusConflict, "that email already has an account")
		case errors.Is(err, store.ErrInvalid):
			writeError(w, http.StatusBadRequest, "invalid account")
		default:
			logError(r.Context(), "signup", err)
			writeError(w, http.StatusInternalServerError, "try again later")
		}
		return
	}
	writeJSON(w, http.StatusCreated, map[string]any{"id": u.ID, "email": u.Email})
}

// maxBodyBytes bounds what a handler reads from a request body.
const maxBodyBytes = 64 << 10

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func writeError(w http.ResponseWriter, status int, msg string) {
	writeJSON(w, status, map[string]string{"error": msg})
}

// app serves web/dist, and index.html for every path that is not a file:
// the client-side router owns those.
func app() http.Handler {
	dist, err := fs.Sub(web.Dist, "dist")
	if err != nil {
		panic(err)
	}
	files := http.FileServerFS(dist)
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if st, err := fs.Stat(dist, strings.TrimPrefix(r.URL.Path, "/")); err != nil || st.IsDir() {
			r.URL.Path = "/"
		}
		files.ServeHTTP(w, r)
	})
}

// cookie, asks the store for the session and the user, and puts the user
// on the request. A request without the cookie, or with one the store does
// not know, reaches next unnamed; the handler answers 401 when it needs a
// user. The cookie path is "/", so the browser sends it to every path.
func (s *Server) session(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		c, err := r.Cookie(SessionCookie)
		if err != nil || c.Value == "" {
			next.ServeHTTP(w, r)
			return
		}
		sess, err := s.store.GetSession(r.Context(), c.Value)
		if err != nil {
			if !errors.Is(err, store.ErrNotFound) {
				logError(r.Context(), "session", err)
			}
			next.ServeHTTP(w, r)
			return
		}
		user, err := s.store.GetUserByID(r.Context(), sess.UserID)
		if err != nil {
			if !errors.Is(err, store.ErrNotFound) {
				logError(r.Context(), "session user", err)
			}
			next.ServeHTTP(w, r)
			return
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), sessionKey{}, user)))
	})
}

// requireUser is the guard of a handler that only a logged-in user may
// reach: it answers 401 to an anonymous request and calls next with the
// user on the request's context. The feature cards wrap their handlers in
// it, so a session cookie is what names the caller everywhere under /api/.
func (s *Server) requireUser(next func(http.ResponseWriter, *http.Request, *store.User)) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user, ok := UserFrom(r.Context())
		if !ok {
			writeError(w, http.StatusUnauthorized, "login required")
			return
		}
		next(w, r, user)
	}
}

// newSessionCookie returns a random cookie value: 32 bytes, URL-safe base
// 64 without padding.
func newSessionCookie() (string, error) {
	b := make([]byte, 32)
	if _, err := rand.Read(b[:]); err != nil {
		return "", err
	}
	return base64.RawURLEncoding.EncodeToString(b[:]), nil
}

// setSessionCookie puts the login cookie on the response, valid until
// expiresAt. The session is HttpOnly, so no script reads it; SameSite=Lax,
// so it travels on a top-level GET (the redirect of /<slug>) but not on
// another site's POST; path "/", so it reaches the API and the app alike;
// and Secure always, because the service is served over https and a session
// must never cross an insecure connection.
func setSessionCookie(w http.ResponseWriter, value string, expiresAt time.Time) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    value,
		Path:     "/",
		Expires:  expiresAt.UTC(),
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
	})
}

// clearSessionCookie drops the login cookie from the browser, with the same
// attributes so the browser matches the one it holds.
func clearSessionCookie(w http.ResponseWriter) {
	http.SetCookie(w, &http.Cookie{
		Name:     SessionCookie,
		Value:    "",
		Path:     "/",
		MaxAge:   -1,
		HttpOnly: true,
		Secure:   true,
		SameSite: http.SameSiteLaxMode,
	})
}

// logError records a failure the handler cannot answer to the client. Its
// message names only the app's own fault: never a cookie, an email or a
// password, which must not land in the logs.
func logError(_ context.Context, what string, err error) {
	log.Printf("server: %s: %v", what, err)
}
