// ListLinksByUser is newest first, each link with its total clicks.
func (d *DB) ListLinksByUser(ctx context.Context, userID int64) ([]store.Link, error) {
	rows, err := d.db.QueryContext(ctx,
		`SELECT `+linkColumns+` FROM links WHERE user_id = ? ORDER BY created_at DESC, id DESC`, userID)
	if err != nil {
		return nil, fmt.Errorf("sqlite: list links: %w", err)
	}
	defer func() { _ = rows.Close() }()
	links := []store.Link{}
	for rows.Next() {
		l, err := scanLink(rows.Scan)
		if err != nil {
			return nil, fmt.Errorf("sqlite: scan link: %w", err)
		}
		links = append(links, l)
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("sqlite: list links: %w", err)
	}
	return links, nil
}
// GetClickStats answers one entry per UTC day of the window ending today,
// 0 for a day without clicks, oldest first. An unknown slug answers
// store.ErrNotFound.
func (d *DB) GetClickStats(ctx context.Context, slug string, days int) ([]store.ClickStat, error) {
	if days <= 0 {
		return nil, fmt.Errorf("sqlite: GetClickStats: %w", store.ErrInvalid)
	}
	var id int64
	err := d.db.QueryRowContext(ctx, `SELECT id FROM links WHERE slug = ?`, slug).Scan(&id)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, store.ErrNotFound
	} else if err != nil {
		return nil, fmt.Errorf("sqlite: stats link: %w", err)
	}
	today := nowUTC()
	first := today.AddDate(0, 0, -(days - 1))
	from := dayOf(first)
	rows, err := d.db.QueryContext(ctx,
		`SELECT day, clicks FROM clicks WHERE link_id = ? AND day >= ? AND day <= ?`,
		id, from, dayOf(today))
	if err != nil {
		return nil, fmt.Errorf("sqlite: stats: %w", err)
	}
	defer func() { _ = rows.Close() }()
	counts := map[string]int64{}
	for rows.Next() {
		var (
			day string
			n   int64
		)
		if err := rows.Scan(&day, &n); err != nil {
			return nil, fmt.Errorf("sqlite: scan stat: %w", err)
		}
		counts[day] = n
	}
	if err := rows.Err(); err != nil {
		return nil, fmt.Errorf("sqlite: stats: %w", err)
	}

	stats := make([]store.ClickStat, 0, days)
	for i := range days {
		day := first.AddDate(0, 0, i).Format("2006-01-02")
		stats = append(stats, store.ClickStat{Day: day, Clicks: counts[day]})
	}
	return stats, nil
}

func scanLink(scan func(dest ...any) error) (store.Link, error) {
	var (
		l       store.Link
		created string
	)
	if err := scan(&l.ID, &l.UserID, &l.Slug, &l.TargetURL, &created, &l.TotalClicks); err != nil {
		return store.Link{}, err
	}
	t, err := time.Parse(time.RFC3339Nano, created)
	if err != nil {
		return store.Link{}, fmt.Errorf("sqlite: link created_at: %w", err)
	}
	l.CreatedAt = t
	return l, nil
}
func (d *DB) CreateLink(ctx context.Context, userID int64, slug, targetURL string) (*store.Link, error) {
	if slug == "" || targetURL == "" {
		return nil, fmt.Errorf("sqlite: CreateLink: %w", store.ErrInvalid)
	}
	if _, err := d.GetUserByID(ctx, userID); err != nil {
		return nil, err
	}
	now := nowUTC()
	res, err := d.db.ExecContext(ctx,
		`INSERT INTO links (user_id, slug, target_url, created_at, total_clicks) VALUES (?, ?, ?, ?, 0)`,
		userID, slug, targetURL, formatTime(now))
	if err != nil {
		if isUnique(err) {
			return nil, store.ErrDuplicate
		}
		return nil, fmt.Errorf("sqlite: create link: %w", err)
	}
	id, err := res.LastInsertId()
	if err != nil {
		return nil, fmt.Errorf("sqlite: created link id: %w", err)
	}
	return &store.Link{ID: id, UserID: userID, Slug: slug, TargetURL: targetURL, CreatedAt: now}, nil
}
func (d *DB) DeleteLink(ctx context.Context, slug string) error {
	res, err := d.db.ExecContext(ctx, `DELETE FROM links WHERE slug = ?`, slug)
	if err != nil {
		return fmt.Errorf("sqlite: delete link: %w", err)
	}
	n, err := res.RowsAffected()
	if err != nil {
		return fmt.Errorf("sqlite: deleted link: %w", err)
	}
	if n == 0 {
		return store.ErrNotFound
	}
	return nil
}
