+// The app's calls to its own API, and the shapes it answers.
+
+export type Me = { id: number; email: string }
+
+export type Link = {
+  slug: string
+  target_url: string
+  created_at: string
+  total_clicks: number
+}
+
+export type ClickStat = { day: string; clicks: number }
+
+export class ApiError extends Error {
+  readonly status: number
+  constructor(status: number, message: string) {
+    super(message)
+    this.name = 'ApiError'
+    this.status = status
+  }
+}
+
+async function request(method: string, path: string, body?: unknown): Promise<Response> {
+  const res = await fetch(path, {
+    method,
+    credentials: 'same-origin',
+    headers: body === undefined ? {} : { 'Content-Type': 'application/json' },
+    body: body === undefined ? undefined : JSON.stringify(body),
+  })
+  if (!res.ok) throw new ApiError(res.status, await errorOf(res))
+  return res
+}
+
+// errorOf reads the {"error": "..."} the API answers with a failure, and
+// falls back to the status when the body says nothing.
+async function errorOf(res: Response): Promise<string> {
+  try {
+    const data = (await res.json()) as { error?: string }
+    if (typeof data.error === 'string' && data.error !== '') return data.error
+  } catch {
+    // a body that is not JSON, or none at all
+  }
+  return `the request failed (${res.status})`
+}
+
+async function json<T>(method: string, path: string, body?: unknown): Promise<T> {
+  const res = await request(method, path, body)
+  return (await res.json()) as T
+}
+
+export function signup(email: string, password: string): Promise<Me> {
+  return json<Me>('POST', '/api/signup', { email, password })
+}
+
+export function login(email: string, password: string): Promise<Me> {
+  return json<Me>('POST', '/api/login', { email, password })
+}
+
+export function logout(): Promise<null> {
+  return request('POST', '/api/logout').then(() => null)
+}
+
+export function getMe(): Promise<Me> {
+  return json<Me>('GET', '/api/me')
+}
+
+export function listLinks(): Promise<Link[]> {
+  return json<{ links: Link[] }>('GET', '/api/links').then((d) => d.links ?? [])
+}
+
+export function createLink(url: string, slug?: string): Promise<Link> {
+  return json<Link>('POST', '/api/links', { url, slug: slug ?? '' })
+}
+
+export function deleteLink(slug: string): Promise<null> {
+  return request('DELETE', `/api/links/${slug}`).then(() => null)
+}
+
+export function getStats(slug: string): Promise<ClickStat[]> {
+  return json<{ stats: ClickStat[] }>('GET', `/api/links/${slug}/stats`).then((d) => d.stats ?? [])
+}
+
+// shortUrl is what a visitor types to reach the link: the origin of the app
+// plus the slug, as the server redirects GET /<slug>.
+export function shortUrl(slug: string): string {
+  return `${window.location.origin}/${slug}`
+}

