+package server_test
+
+import (
+	"bytes"
+	"context"
+	"encoding/json"
+	"io"
+	"net/http"
+	"net/http/httptest"
+	"strings"
+	"testing"
+	"time"
+
+	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/server"
+	"git.aisoftwarefactory.world/linkshort2/linkshort2/internal/store"
+)
+
+// TestAppServesTheSPA is the frontend card's own end: every path under /app/
+// answers the index page, so the client-side router of /signup, /login,
+// /links and /links/:slug can take the URL over.
+func TestAppServesTheSPA(t *testing.T) {
+	srv := httptest.NewServer(server.New(server.Config{DataDir: t.TempDir()}))
+	defer srv.Close()
+
+	for _, path := range []string{"/app/", "/app/signup", "/app/login", "/app/links", "/app/links/abc1234"} {
+		res, err := http.Get(srv.URL + path)
+		if err != nil {
+			t.Fatal(err)
+		}
+		body, err := io.ReadAll(res.Body)
+		_ = res.Body.Close()
+		if err != nil {
+			t.Fatal(err)
+		}
+		if res.StatusCode != http.StatusOK {
+			t.Errorf("GET %s: status %d, want 200", path, res.StatusCode)
+		}
+		if !strings.Contains(string(body), `<div id="root">`) {
+			t.Errorf("GET %s: body %q, want the SPA's root div", path, body)
+		}
+	}
+}
+
+// TestLinksAPIOwnedByTheUser is what the my links page calls: GET /api/links
+// names the caller's own links with their click counts, DELETE drops one of
+// them, and another user's slug answers 404 and stays where it is.
+func TestLinksAPIOwnedByTheUser(t *testing.T) {
+	st := newLinkStore()
+	srv := httptest.NewServer(server.New(server.Config{Store: st}))
+	defer srv.Close()
+
+	first, second := sessionOf("first-session"), sessionOf("second-session")
+
+	links := listLinksAs(t, srv, first)
+	if len(links) != 1 || links[0]["slug"] != "own-slug" {
+		t.Fatalf("GET /api/links as the first user: %v, want only own-slug", links)
+	}
+	if got := links[0]["total_clicks"]; got != float64(4) {
+		t.Errorf("GET /api/links: total_clicks %v, want 4", got)
+	}
+	if _, ok := links[0]["user_id"]; ok {
+		t.Errorf("GET /api/links: the body names a user_id, which no page needs")
+	}
+	if _, ok := links[0]["target_url"]; !ok {
+		t.Errorf("GET /api/links: the body hides the target_url a page copies from")
+	}
+
+	if code := doAs(t, srv, http.MethodDelete, "/api/links/theirs-slug", second); code != http.StatusNoContent {
+		t.Errorf("DELETE of one's own link: status %d, want 204", code)
+	}
+	if code := doAs(t, srv, http.MethodDelete, "/api/links/own-slug", second); code != http.StatusNotFound {
+		t.Errorf("DELETE of another user's link: status %d, want 404", code)
+	}
+	if !st.known("own-slug") {
+		t.Errorf("the first user's link vanished after a stranger asked for its delete")
+	}
+
+	if code := doAs(t, srv, http.MethodDelete, "/api/links/own-slug", first); code != http.StatusNoContent {
+		t.Fatalf("DELETE of one's own link: status %d, want 204", code)
+	}
+	if got := listLinksAs(t, srv, first); len(got) != 0 {
+		t.Errorf("GET /api/links after the delete: %v, want none", got)
+	}
+
+	if code := doAs(t, srv, http.MethodGet, "/api/links", sessionOf("")); code != http.StatusUnauthorized {
+		t.Errorf("GET /api/links without a session: status %d, want 401", code)
+	}
+}
+
+func sessionOf(cookie string) *http.Cookie {
+	return &http.Cookie{Name: "session", Value: cookie}
+}
+
+func doAs(t *testing.T, srv *httptest.Server, method, path string, cookie *http.Cookie) int {
+	t.Helper()
+	req, err := http.NewRequest(method, srv.URL+path, bytes.NewReader(nil))
+	if err != nil {
+		t.Fatal(err)
+	}
+	req.AddCookie(cookie)
+	res, err := srv.Client().Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	_, _ = io.Copy(io.Discard, res.Body)
+	_ = res.Body.Close()
+	return res.StatusCode
+}
+
+func listLinksAs(t *testing.T, srv *httptest.Server, cookie *http.Cookie) []map[string]any {
+	t.Helper()
+	req, err := http.NewRequest(http.MethodGet, srv.URL+"/api/links", nil)
+	if err != nil {
+		t.Fatal(err)
+	}
+	req.AddCookie(cookie)
+	res, err := srv.Client().Do(req)
+	if err != nil {
+		t.Fatal(err)
+	}
+	defer func() { _ = res.Body.Close() }()
+	if res.StatusCode != http.StatusOK {
+		t.Fatalf("GET /api/links: status %d, want 200", res.StatusCode)
+	}
+	var body struct {
+		Links []map[string]any `json:"links"`
+	}
+	if err := json.NewDecoder(res.Body).Decode(&body); err != nil {
+		t.Fatalf("GET /api/links: body is not JSON: %v", err)
+	}
+	return body.Links
+}
+
+// linkStore is the store contract as the my links page sees it: two users
+// with a session each, the first holding own-slug, the second theirs-slug.
+type linkStore struct {
+	store.Store
+	links []store.Link
+}
+
+func newLinkStore() *linkStore {
+	now := time.Now().UTC()
+	return &linkStore{links: []store.Link{
+		{ID: 1, UserID: 1, Slug: "own-slug", TargetURL: "https://example.com/one", CreatedAt: now, TotalClicks: 4},
+		{ID: 2, UserID: 2, Slug: "theirs-slug", TargetURL: "https://example.com/two", CreatedAt: now, TotalClicks: 0},
+	}}
+}
+
+func (s *linkStore) known(slug string) bool {
+	for _, l := range s.links {
+		if l.Slug == slug {
+			return true
+		}
+	}
+	return false
+}
+
+func (*linkStore) GetUserByID(_ context.Context, id int64) (*store.User, error) {
+	emails := map[int64]string{1: "first@example.com", 2: "second@example.com"}
+	email, ok := emails[id]
+	if !ok {
+		return nil, store.ErrNotFound
+	}
+	return &store.User{ID: id, Email: email}, nil
+}
+
+func (*linkStore) GetSession(_ context.Context, cookie string) (*store.Session, error) {
+	userID := map[string]int64{"first-session": 1, "second-session": 2}[cookie]
+	if userID == 0 {
+		return nil, store.ErrNotFound
+	}
+	return &store.Session{Cookie: cookie, UserID: userID, ExpiresAt: time.Now().UTC().Add(time.Hour)}, nil
+}
+
+func (s *linkStore) ListLinksByUser(_ context.Context, userID int64) ([]store.Link, error) {
+	out := []store.Link{}
+	for _, l := range s.links {
+		if l.UserID == userID {
+			out = append(out, l)
+		}
+	}
+	return out, nil
+}
+
+func (s *linkStore) GetLinkBySlug(_ context.Context, slug string) (*store.Link, error) {
+	for _, l := range s.links {
+		if l.Slug == slug {
+			got := l
+			return &got, nil
+		}
+	}
+	return nil, store.ErrNotFound
+}
+
+func (s *linkStore) DeleteLink(_ context.Context, slug string) error {
+	for i, l := range s.links {
+		if l.Slug == slug {
+			s.links = append(s.links[:i], s.links[i+1:]...)
+			return nil
+		}
+	}
+	return store.ErrNotFound
+}
